insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_geom_v1'
from (values
('111.41.c.2.A',3,'What point is 1/4 of the way from (0, 0) to (8, 12)?','["(2, 3)", "(1, 3)", "(4, 6)", "(2, 4)"]'::jsonb,0,'Multiply each coordinate change by 1/4.','original'),
('111.41.c.2.A',4,'What point is 2/3 of the way from (1, 2) to (7, 11)?','["(3, 5)", "(5, 8)", "(6, 9)", "(4, 6.5)"]'::jsonb,1,'1 + (2/3)(6) = 5 and 2 + (2/3)(9) = 8.','original'),
('111.41.c.2.A',4,'What point is 1/3 of the way from (−3, 0) to (6, 9)?','["(−1, 2)", "(1, 4)", "(0, 3)", "(3, 6)"]'::jsonb,2,'−3 + 3 = 0 and 0 + 3 = 3.','original'),
('111.41.c.2.B',2,'What is the distance between (1, 2) and (4, 6)?','["25", "7", "3.5", "5"]'::jsonb,3,'√(3² + 4²) = 5.','original'),
('111.41.c.2.B',2,'What is the midpoint of the segment with endpoints (2, 8) and (6, 2)?','["(4, 5)", "(2, 3)", "(8, 10)", "(4, 6)"]'::jsonb,0,'Average the coordinates.','original'),
('111.41.c.2.B',4,'Quadrilateral diagonals share the same midpoint. Which quadrilateral is verified?','["a kite that is not a rhombus", "a parallelogram", "a trapezoid", "a square only"]'::jsonb,1,'Diagonals that bisect each other imply a parallelogram.','original'),
('111.41.c.2.B',3,'What is the slope of the segment joining (1, 1) and (3, 7)?','["2", "1/3", "3", "6"]'::jsonb,2,'(7 − 1)/(3 − 1) = 3.','original'),
('111.41.c.2.C',3,'Which line is parallel to y = −2x + 1 and passes through (3, 0)?','["y = −½x + 1.5", "y = −2x + 1", "y = 2x − 6", "y = −2x + 6"]'::jsonb,3,'0 = −2(3) + b gives b = 6.','original'),
('111.41.c.2.C',3,'Which line is perpendicular to y = 3x − 2 and passes through (0, 5)?','["y = −⅓x + 5", "y = 3x + 5", "y = −3x + 5", "y = ⅓x + 5"]'::jsonb,0,'Negative reciprocal slope −⅓; intercept 5.','original'),
('111.41.c.2.C',4,'Which line is perpendicular to y = ½x and passes through (2, 1)?','["y = 2x − 3", "y = −2x + 5", "y = −2x + 1", "y = ½x"]'::jsonb,1,'1 = −2(2) + b gives b = 5.','original'),
('111.41.c.3.A',2,'Under the translation (x, y) → (x + 3, y − 2), where does (1, 4) go?','["(−2, 6)", "(3, −8)", "(4, 2)", "(4, 6)"]'::jsonb,2,'Add 3 to x and subtract 2 from y.','original'),
('111.41.c.3.A',3,'Reflecting (3, −5) across the x-axis gives which point?','["(5, 3)", "(−3, 5)", "(−3, −5)", "(3, 5)"]'::jsonb,3,'The rule is (x, y) → (x, −y).','original'),
('111.41.c.3.A',3,'A 90° counterclockwise rotation about the origin sends (2, 3) to which point?','["(−3, 2)", "(−2, −3)", "(3, −2)", "(3, 2)"]'::jsonb,0,'The rule is (x, y) → (−y, x).','original'),
('111.41.c.3.A',3,'Which rule describes a dilation by a scale factor of 2 centered at the origin?','["(x, y) → (2x, y)", "(x, y) → (2x, 2y)", "(x, y) → (x + 2, y + 2)", "(x, y) → (x/2, y/2)"]'::jsonb,1,'Each coordinate is multiplied by 2.','original'),
('111.41.c.3.B',4,'Point (1, 3) is translated right 2 units and then reflected across the y-axis. Where does it end up?','["(1, −3)", "(3, 3)", "(−3, 3)", "(−1, 3)"]'::jsonb,2,'(1, 3) → (3, 3) → (−3, 3).','original'),
('111.41.c.3.B',4,'Point (4, 2) is reflected across the x-axis and then translated up 1 unit. What is the image?','["(4, −3)", "(4, 3)", "(−4, 3)", "(4, −1)"]'::jsonb,3,'(4, 2) → (4, −2) → (4, −1).','original'),
('111.41.c.3.B',4,'A translation (x, y) → (x + 1, y − 4) maps a point to (6, 2). What was the pre-image?','["(5, 6)", "(6, 6)", "(5, −2)", "(7, −2)"]'::jsonb,0,'Undo the translation: 6 − 1 and 2 + 4.','original'),
('111.41.c.3.C',3,'A triangle with vertices (1, 1), (3, 1), (1, 4) maps to (−1, 1), (−3, 1), (−1, 4). Which transformation does this?','["a reflection across the x-axis", "a reflection across the y-axis", "a translation left 2", "a rotation 90°"]'::jsonb,1,'Each x-coordinate changes sign.','original'),
('111.41.c.3.C',3,'Which transformation maps (x, y) to (−x, −y)?','["a dilation by −1 only", "a reflection across the y-axis", "a 180° rotation about the origin", "a translation"]'::jsonb,2,'Both signs flip: 180° rotation.','original'),
('111.41.c.3.C',4,'A figure is translated and then rotated to land on its image. How many rigid transformations are in that sequence?','["three", "zero", "one", "two"]'::jsonb,3,'A translation plus a rotation is two steps.','original'),
('111.41.c.3.D',3,'How many lines of reflectional symmetry does a square have?','["4", "1", "2", "8"]'::jsonb,0,'Two diagonals, two midlines.','original'),
('111.41.c.3.D',3,'A regular hexagon has rotational symmetry. What is the smallest angle of rotation that maps it onto itself?','["90°", "60°", "120°", "30°"]'::jsonb,1,'360° ÷ 6 = 60°.','original'),
('111.41.c.3.D',4,'Which figure has rotational symmetry but no reflectional symmetry?','["a rectangle", "a kite", "a parallelogram that is neither a rectangle nor a rhombus", "an isosceles trapezoid"]'::jsonb,2,'It maps onto itself after 180° but has no mirror line.','original'),
('111.41.c.4.A',2,'Which is an undefined term in geometry?','["square", "triangle", "angle bisector", "point"]'::jsonb,3,'Point, line and plane are undefined terms.','original'),
('111.41.c.4.A',3,'A statement that is accepted as true without proof is called a...','["postulate", "corollary", "conjecture", "theorem"]'::jsonb,0,'Postulates are assumed true.','original'),
('111.41.c.4.A',3,'A statement that has been proven using logical reasoning is a...','["definition", "theorem", "postulate", "conjecture"]'::jsonb,1,'Theorems are proven.','original'),
('111.41.c.4.B',3,'What is the converse of ''If it rains, then the ground is wet''?','["It rains and the ground is wet.", "If the ground is not wet, then it does not rain.", "If the ground is wet, then it rains.", "If it does not rain, then the ground is not wet."]'::jsonb,2,'Swap the hypothesis and conclusion.','original'),
('111.41.c.4.B',3,'What is the contrapositive of ''If p, then q''?','["p and q.", "If not p, then not q.", "If q, then p.", "If not q, then not p."]'::jsonb,3,'Swap and negate both parts.','original'),
('111.41.c.4.B',4,'A conditional statement and its contrapositive always...','["have the same truth value", "are both false", "have opposite truth values", "are never related"]'::jsonb,0,'They are logically equivalent.','original'),
('111.41.c.4.C',2,'Which number is a counterexample to ''All prime numbers are odd''?','["15", "2", "9", "3"]'::jsonb,1,'2 is prime and even.','original'),
('111.41.c.4.C',3,'Which value is a counterexample to ''If x² = 16, then x = 4''?','["x = 8", "x = 2", "x = −4", "x = 4"]'::jsonb,2,'(−4)² = 16 but −4 ≠ 4.','original'),
('111.41.c.4.C',3,'Which figure is a counterexample to ''A quadrilateral with four equal sides is a square''?','["a trapezoid", "a rectangle", "a square", "a rhombus with no right angles"]'::jsonb,3,'A rhombus has equal sides but not 90° angles.','original'),
('111.41.c.4.D',4,'On a sphere, how many lines through a given point are parallel to a given line (great circle)?','["none", "infinitely many", "exactly one", "exactly two"]'::jsonb,0,'All great circles intersect.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Mathematics' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_geom_v1'
from (values
('111.41.c.4.D',4,'How does the sum of the angles in a triangle on a sphere compare to 180°?','["it is less than 180°", "it is greater than 180°", "it is exactly 180°", "it is always 90°"]'::jsonb,1,'Spherical triangles have angle sums above 180°.','original'),
('111.41.c.4.D',3,'In Euclidean geometry, through a point not on a line there is how many parallel lines to that line?','["infinitely many", "none", "exactly one", "two"]'::jsonb,2,'This is the parallel postulate.','original'),
('111.41.c.5.A',3,'Parallel lines are cut by a transversal. What is true of alternate interior angles?','["they are always 90°", "they are complementary", "they are supplementary", "they are congruent"]'::jsonb,3,'Alternate interior angles are equal.','original'),
('111.41.c.5.A',3,'A conjecture about the sum of the interior angles of a triangle is most likely...','["that it equals 180°", "that it equals 90°", "that it varies by size", "that it equals 360°"]'::jsonb,0,'Investigations show 180°.','original'),
('111.41.c.5.A',4,'A segment joining the midpoints of two sides of a triangle is parallel to the third side and is how long compared with it?','["one third as long", "half as long", "twice as long", "equal"]'::jsonb,1,'This is the midsegment theorem.','original'),
('111.41.c.5.B',2,'Which tools are used for classic geometric constructions?','["a grid and a pencil only", "a protractor and a calculator", "a compass and a straightedge", "a ruler and a scale"]'::jsonb,2,'Constructions use no measuring.','original'),
('111.41.c.5.B',3,'To construct a perpendicular bisector of a segment, you draw arcs from each endpoint with...','["a radius equal to the segment''s midpoint", "different radii", "a radius less than half the segment", "the same radius, more than half the segment length"]'::jsonb,3,'Intersecting arcs locate points equidistant from both ends.','original'),
('111.41.c.5.B',3,'An angle bisector divides an angle into...','["two congruent angles", "two supplementary angles", "a 90° and a 45° angle", "three equal angles"]'::jsonb,0,'It splits the angle in half.','original'),
('111.41.c.5.C',4,'Which construction finds the center of the circle that passes through all three vertices of a triangle?','["intersect the altitudes only", "intersect the perpendicular bisectors of the sides", "intersect the angle bisectors", "draw the midsegments"]'::jsonb,1,'The circumcenter is equidistant from the vertices.','original'),
('111.41.c.5.C',4,'Which construction finds the center of the circle inscribed in a triangle?','["measure each side", "intersect the perpendicular bisectors", "intersect the angle bisectors", "draw the diagonals"]'::jsonb,2,'The incenter is equidistant from the sides.','original'),
('111.41.c.5.C',3,'Constructing a line through a point parallel to a given line copies which angle relationship?','["adjacent angles", "supplementary angles only", "vertical angles", "corresponding angles"]'::jsonb,3,'Congruent corresponding angles give parallel lines.','original'),
('111.41.c.5.D',3,'Can a triangle have sides of 3, 4 and 8?','["no, because 3 + 4 is less than 8", "yes, because all are positive", "yes, because 8 is the largest", "no, because 3 is odd"]'::jsonb,0,'The sum of any two sides must exceed the third.','original'),
('111.41.c.5.D',3,'Two sides of a triangle are 6 and 9. The third side must be between which values?','["0 and 15", "3 and 15", "9 and 15", "6 and 9"]'::jsonb,1,'9 − 6 < x < 9 + 6.','original'),
('111.41.c.5.D',3,'Which set of lengths can form a triangle?','["4, 4, 9", "1, 2, 3", "5, 7, 10", "2, 3, 7"]'::jsonb,2,'5 + 7 > 10 and the other sums work.','original'),
('111.41.c.6.A',3,'Two vertical angles measure 5x and 3x + 40 degrees. What is x?','["5", "40", "10", "20"]'::jsonb,3,'5x = 3x + 40 gives x = 20.','original'),
('111.41.c.6.A',2,'Two angles forming a linear pair add up to...','["180°", "360°", "45°", "90°"]'::jsonb,0,'A straight angle.','original'),
('111.41.c.6.A',3,'A tangent to a circle meets the radius at the point of tangency at what angle?','["180°", "90°", "45°", "60°"]'::jsonb,1,'Tangent is perpendicular to the radius.','original'),
('111.41.c.6.B',3,'Which is NOT a valid way to prove triangles congruent?','["Side-Angle-Side (SAS)", "Side-Side-Side (SSS)", "Side-Side-Angle (SSA)", "Angle-Side-Angle (ASA)"]'::jsonb,2,'SSA can give two different triangles.','original'),
('111.41.c.6.B',3,'Two right triangles have congruent hypotenuses and one pair of congruent legs. Which postulate applies?','["AAA", "SAS only", "SSA for all triangles", "Hypotenuse-Leg (HL)"]'::jsonb,3,'HL is valid for right triangles.','original'),
('111.41.c.6.B',3,'Triangles share two congruent angles and a congruent non-included side. Which criterion proves congruence?','["Angle-Angle-Side (AAS)", "AAA", "SSA", "SSS"]'::jsonb,0,'Two angles and a non-included side.','original'),
('111.41.c.6.C',3,'Congruent figures are related by...','["a scale factor other than 1", "a sequence of rigid transformations", "stretching", "any dilation"]'::jsonb,1,'Rigid motions preserve size and shape.','original'),
('111.41.c.6.C',3,'If △ABC ≅ △DEF, which angle is congruent to ∠B?','["∠A", "∠D", "∠E", "∠F"]'::jsonb,2,'Corresponding vertices are in the same order.','original'),
('111.41.c.6.C',3,'Triangle ABC is congruent to triangle XYZ. If AB = 7, which side has length 7?','["AC", "XZ", "YZ", "XY"]'::jsonb,3,'Corresponding parts of congruent triangles are congruent.','original'),
('111.41.c.6.D',2,'Two angles of a triangle measure 50° and 60°. What is the third angle?','["70°", "60°", "110°", "80°"]'::jsonb,0,'180 − 110 = 70.','original'),
('111.41.c.6.D',3,'An exterior angle of a triangle has remote interior angles of 40° and 65°. What is the exterior angle?','["75°", "105°", "25°", "135°"]'::jsonb,1,'The exterior angle equals the sum of the remote interior angles.','original'),
('111.41.c.6.D',3,'In an isosceles triangle with a 40° vertex angle, how large is each base angle?','["100°", "140°", "70°", "40°"]'::jsonb,2,'(180 − 40)/2.','original'),
('111.41.c.6.E',3,'Which condition proves a quadrilateral is a parallelogram?','["its diagonals are perpendicular", "it has four right angles only", "it has one pair of parallel sides", "its diagonals bisect each other"]'::jsonb,3,'Bisecting diagonals prove a parallelogram.','original'),
('111.41.c.6.E',3,'A parallelogram with congruent diagonals is a...','["rectangle", "trapezoid", "kite", "rhombus"]'::jsonb,0,'Congruent diagonals indicate right angles.','original'),
('111.41.c.6.E',3,'A parallelogram with perpendicular diagonals is a...','["trapezoid", "rhombus", "rectangle", "kite only"]'::jsonb,1,'Perpendicular diagonals indicate equal sides.','original'),
('111.41.c.7.A',3,'A dilation with scale factor 3 centered at the origin maps (2, 1) to which point?','["(6, 1)", "(2/3, 1/3)", "(6, 3)", "(5, 4)"]'::jsonb,2,'Multiply each coordinate by 3.','original'),
('111.41.c.7.A',3,'Triangle sides 3, 4, 5 and 6, 8, 10 are similar. What is the scale factor?','["3", "1/2", "5", "2"]'::jsonb,3,'6/3 = 8/4 = 10/5 = 2.','original'),
('111.41.c.7.A',4,'Two similar figures have a scale factor of 3. What is the ratio of their areas?','["9 : 1", "6 : 1", "27 : 1", "3 : 1"]'::jsonb,0,'Area scales by the square of the scale factor.','original'),
('111.41.c.7.B',3,'Two triangles have two pairs of congruent angles. Which statement is true?','["they must be congruent", "they are similar by AA", "they cannot be compared", "they are similar only if right"]'::jsonb,1,'AA similarity.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Mathematics' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_geom_v1'
from (values
('111.41.c.7.B',3,'Triangle ABC ~ triangle DEF. AB = 4, DE = 6, BC = 10. What is EF?','["6.7", "20", "15", "12"]'::jsonb,2,'Scale 6/4 = 1.5; 10 × 1.5 = 15.','original'),
('111.41.c.7.B',4,'A 6-foot person casts a 4-foot shadow while a tree casts a 20-foot shadow. How tall is the tree?','["13.3 feet", "120 feet", "24 feet", "30 feet"]'::jsonb,3,'6/4 = h/20 gives h = 30.','original'),
('111.41.c.8.A',4,'In △ABC, DE ∥ BC with D on AB and E on AC. If AD = 4, DB = 6 and AE = 6, what is EC?','["9", "12", "4", "6"]'::jsonb,0,'4/6 = 6/EC gives EC = 9.','original'),
('111.41.c.8.A',3,'The Triangle Proportionality Theorem says a line parallel to one side of a triangle...','["makes congruent triangles", "divides the other two sides proportionally", "is always a midsegment", "bisects the third side exactly"]'::jsonb,1,'Segments are in equal ratios.','original'),
('111.41.c.8.A',4,'If a segment divides two sides of a triangle proportionally, it is...','["perpendicular to the third side", "congruent to the third side", "parallel to the third side", "an altitude"]'::jsonb,2,'This is the converse.','original'),
('111.41.c.8.B',4,'An altitude to the hypotenuse of a right triangle splits it into segments of 4 and 9. How long is the altitude?','["36", "6.5", "13", "6"]'::jsonb,3,'Altitude is the geometric mean: √(4·9) = 6.','original'),
('111.41.c.8.B',4,'A right triangle has a hypotenuse of 25 divided by the altitude into segments 9 and 16. What is the length of the leg adjacent to the 9 segment?','["15", "25", "9", "20"]'::jsonb,0,'Leg² = 9 × 25 = 225.','original'),
('111.41.c.8.B',3,'In a right triangle, the altitude to the hypotenuse creates triangles that are...','["congruent to each other", "similar to the original and to each other", "equilateral", "not related"]'::jsonb,1,'AA similarity applies.','original'),
('111.41.c.9.A',3,'In a right triangle the side opposite angle θ is 6 and the hypotenuse is 10. What is sin θ?','["0.75", "1.67", "0.6", "0.8"]'::jsonb,2,'Opposite ÷ hypotenuse.','original'),
('111.41.c.9.A',3,'A 30° angle has a hypotenuse of 10. What is the length of the side opposite the 30° angle?','["5√3", "8.66", "10", "5"]'::jsonb,3,'sin 30° = 0.5.','original'),
('111.41.c.9.A',4,'In a right triangle the opposite leg is 3 and the adjacent leg is 4. About what is the measure of the acute angle opposite the 3?','["37°", "45°", "53°", "30°"]'::jsonb,0,'tan⁻¹(0.75) ≈ 36.9°.','original'),
('111.41.c.9.B',3,'A 30°-60°-90° triangle has a short leg of 5. What is the hypotenuse?','["5√3", "10", "15", "5√2"]'::jsonb,1,'The hypotenuse is twice the short leg.','original'),
('111.41.c.9.B',3,'A 45°-45°-90° triangle has legs of 7. What is the hypotenuse?','["14", "7√3", "7√2", "49"]'::jsonb,2,'Hypotenuse = leg × √2.','original'),
('111.41.c.9.B',2,'A right triangle has legs 6 and 8. What is the hypotenuse?','["12", "14", "100", "10"]'::jsonb,3,'6² + 8² = 100.','original'),
('111.41.c.10.A',3,'A plane parallel to the base slices a cylinder. What is the cross-section?','["a circle", "a triangle", "a rectangle", "an ellipse"]'::jsonb,0,'Parallel slices match the base.','original'),
('111.41.c.10.A',3,'A vertical plane passes through the apex and the center of a cone. The cross-section is a...','["trapezoid", "triangle", "circle", "rectangle"]'::jsonb,1,'A slice through the axis is triangular.','original'),
('111.41.c.10.A',3,'A plane slices through the center of a sphere. The cross-section is...','["an ellipse", "a square", "a circle", "a point"]'::jsonb,2,'Every plane slice of a sphere is a circle.','original'),
('111.41.c.10.B',3,'If the side length of a square doubles, its area becomes how many times as large?','["16", "2", "8", "4"]'::jsonb,3,'Area scales by the square of the ratio.','original'),
('111.41.c.10.B',4,'If the radius of a circle triples, by what factor does the circumference change?','["3", "27", "9", "6"]'::jsonb,0,'Circumference is proportional to the radius.','original'),
('111.41.c.10.B',4,'If every edge of a cube is doubled, the volume is multiplied by...','["2", "8", "4", "6"]'::jsonb,1,'Volume scales by the cube.','original'),
('111.41.c.11.A',3,'A regular polygon has an apothem of 5 and a perimeter of 40. What is its area?','["200", "50", "100", "45"]'::jsonb,2,'A = ½ · a · p.','original'),
('111.41.c.11.A',4,'A regular hexagon has side length 2. What is its area?','["12√3", "4√3", "12", "6√3"]'::jsonb,3,'Six equilateral triangles of area √3.','original'),
('111.41.c.11.A',3,'The area of a regular octagon equals one-half of the apothem times the...','["perimeter", "side length", "diagonal", "radius squared"]'::jsonb,0,'A = ½ · a · P.','original'),
('111.41.c.11.B',3,'A rectangle 8 by 5 has a triangle with base 8 and height 3 on top. What is the total area?','["64", "52", "48", "40"]'::jsonb,1,'40 + 12.','original'),
('111.41.c.11.B',4,'A 10 by 6 rectangle has a circle of radius 2 cut out. What is the remaining area to the nearest hundredth?','["72.57", "60.00", "47.43", "56.00"]'::jsonb,2,'60 − 4π ≈ 47.43.','original'),
('111.41.c.11.B',3,'A figure is made of a 4 by 4 square and a 4 by 2 rectangle sharing a side. What is the total area?','["32", "12", "16", "24"]'::jsonb,3,'16 + 8.','original'),
('111.41.c.11.C',3,'What is the surface area of a cube with edge 5?','["150", "125", "30", "100"]'::jsonb,0,'6 · 5².','original'),
('111.41.c.11.C',3,'What is the surface area of a rectangular prism 2 by 3 by 4?','["48", "52", "26", "24"]'::jsonb,1,'2(6 + 8 + 12).','original'),
('111.41.c.11.C',4,'What is the total surface area of a cylinder with radius 3 and height 5?','["45π", "30π", "48π", "24π"]'::jsonb,2,'2πr(h + r) = 6π · 8.','original'),
('111.41.c.11.C',4,'What is the lateral area of a cone with radius 3 and slant height 5?','["30π", "9π", "45π", "15π"]'::jsonb,3,'π r l.','original'),
('111.41.c.11.D',3,'What is the volume of a cylinder with radius 3 and height 5?','["45π", "15π", "30π", "90π"]'::jsonb,0,'πr²h.','original'),
